"use client";

import Link from "next/link";
import { motion } from "framer-motion";
import {
  ArrowLeft,
  Terminal,
  Code,
  Globe,
  Network,
  ChevronRight,
  Copy,
  Check,
} from "lucide-react";
import { useState } from "react";

export default function QuickStartPage() {
  const [copied, setCopied] = useState(false);
  const basePath = process.env.NEXT_PUBLIC_BASE_PATH || "/ip-address-database";

  const copyToClipboard = async (text: string) => {
    try {
      await navigator.clipboard.writeText(text);
      setCopied(true);
      setTimeout(() => setCopied(false), 2000);
    } catch (err) {
      console.error("Failed to copy:", err);
    }
  };

  const codeExamples = {
    fetchCountries: `fetch('${basePath}/data/country.json')
  .then(res => res.json())
  .then(data => {
    console.log('Total countries:', data.total_countries);
    console.log('Countries:', data.countries);
  });`,

    fetchCountry: `fetch('${basePath}/data/country/US/get.json')
  .then(res => res.json())
  .then(data => {
    console.log('US networks:', data);
  });`,

    fetchASN: `fetch('${basePath}/data/asn/US/12311/get.json')
  .then(res => res.json())
  .then(data => {
    console.log('AS12311 data:', data);
  });`,

    fetchASNs: `fetch('${basePath}/data/asn/US/get.json')
  .then(res => res.json())
  .then(data => {
    console.log('US ASNs:', data);
  });`,
  };

  return (
    <div className="space-y-6">
      {/* Back */}
      <Link
        href="/docs"
        className="inline-flex items-center gap-2 text-[#6f8a7d] hover:text-[#c6d2ca] transition-colors font-mono text-sm"
      >
        <ArrowLeft size={16} />
        Back to Documentation
      </Link>

      {/* Header */}
      <div className="space-y-3">
        <div className="flex items-center gap-3">
          <span className="text-xs font-mono font-bold text-[#22e57a] tracking-widest uppercase bg-[rgba(34,229,122,.08)] px-3 py-1 rounded-md border border-[rgba(34,229,122,.1)]">
            Getting Started
          </span>
        </div>
        <h1 className="text-3xl md:text-4xl font-bold font-mono text-[#f2fff8]">
          Quick Start Guide
        </h1>
        <p className="text-[#93a79d] font-mono text-lg max-w-2xl">
          Learn how to fetch and use IP database data in your application.
        </p>
      </div>

      {/* Steps */}
      <div className="space-y-6">
        <div className="bg-[rgba(34,229,122,.03)] border border-[rgba(34,229,122,.08)] rounded-xl p-6">
          <h2 className="text-lg font-mono font-bold text-[#f2fff8] flex items-center gap-2">
            <span className="text-[#22e57a]">1.</span>
            Fetch Country List
          </h2>
          <p className="text-[#6f8a7d] font-mono text-sm mt-1">
            Get a list of all countries with their network counts.
          </p>
          <div className="relative mt-3">
            <pre className="bg-[#0a100d] border border-[rgba(34,229,122,.06)] rounded-lg p-4 overflow-x-auto font-mono text-sm text-[#7fe9ab]">
              {codeExamples.fetchCountries}
            </pre>
            <button
              onClick={() => copyToClipboard(codeExamples.fetchCountries)}
              className="absolute top-3 right-3 p-1.5 rounded-md bg-[rgba(34,229,122,.06)] hover:bg-[rgba(34,229,122,.1)] transition-colors"
            >
              {copied ? (
                <Check size={14} className="text-[#22e57a]" />
              ) : (
                <Copy size={14} className="text-[#6f8a7d]" />
              )}
            </button>
          </div>
        </div>

        <div className="bg-[rgba(34,229,122,.03)] border border-[rgba(34,229,122,.08)] rounded-xl p-6">
          <h2 className="text-lg font-mono font-bold text-[#f2fff8] flex items-center gap-2">
            <span className="text-[#22e57a]">2.</span>
            Fetch Country Data
          </h2>
          <p className="text-[#6f8a7d] font-mono text-sm mt-1">
            Get detailed network data for a specific country.
          </p>
          <div className="relative mt-3">
            <pre className="bg-[#0a100d] border border-[rgba(34,229,122,.06)] rounded-lg p-4 overflow-x-auto font-mono text-sm text-[#7fe9ab]">
              {codeExamples.fetchCountry}
            </pre>
            <button
              onClick={() => copyToClipboard(codeExamples.fetchCountry)}
              className="absolute top-3 right-3 p-1.5 rounded-md bg-[rgba(34,229,122,.06)] hover:bg-[rgba(34,229,122,.1)] transition-colors"
            >
              {copied ? (
                <Check size={14} className="text-[#22e57a]" />
              ) : (
                <Copy size={14} className="text-[#6f8a7d]" />
              )}
            </button>
          </div>
        </div>

        <div className="bg-[rgba(34,229,122,.03)] border border-[rgba(34,229,122,.08)] rounded-xl p-6">
          <h2 className="text-lg font-mono font-bold text-[#f2fff8] flex items-center gap-2">
            <span className="text-[#22e57a]">3.</span>
            Fetch ASN Data
          </h2>
          <p className="text-[#6f8a7d] font-mono text-sm mt-1">
            Get Autonomous System Number details for a country or specific ASN.
          </p>
          <div className="grid grid-cols-1 md:grid-cols-2 gap-4 mt-3">
            <div className="relative">
              <h4 className="text-xs font-mono text-[#6f8a7d] mb-1">
                All ASNs in a country
              </h4>
              <pre className="bg-[#0a100d] border border-[rgba(34,229,122,.06)] rounded-lg p-3 overflow-x-auto font-mono text-xs text-[#7fe9ab]">
                {codeExamples.fetchASNs}
              </pre>
              <button
                onClick={() => copyToClipboard(codeExamples.fetchASNs)}
                className="absolute top-7 right-2 p-1 rounded-md bg-[rgba(34,229,122,.06)] hover:bg-[rgba(34,229,122,.1)] transition-colors"
              >
                {copied ? (
                  <Check size={12} className="text-[#22e57a]" />
                ) : (
                  <Copy size={12} className="text-[#6f8a7d]" />
                )}
              </button>
            </div>
            <div className="relative">
              <h4 className="text-xs font-mono text-[#6f8a7d] mb-1">
                Specific ASN
              </h4>
              <pre className="bg-[#0a100d] border border-[rgba(34,229,122,.06)] rounded-lg p-3 overflow-x-auto font-mono text-xs text-[#7fe9ab]">
                {codeExamples.fetchASN}
              </pre>
              <button
                onClick={() => copyToClipboard(codeExamples.fetchASN)}
                className="absolute top-7 right-2 p-1 rounded-md bg-[rgba(34,229,122,.06)] hover:bg-[rgba(34,229,122,.1)] transition-colors"
              >
                {copied ? (
                  <Check size={12} className="text-[#22e57a]" />
                ) : (
                  <Copy size={12} className="text-[#6f8a7d]" />
                )}
              </button>
            </div>
          </div>
        </div>
      </div>

      {/* Next Steps */}
      <div className="bg-[rgba(34,229,122,.03)] border border-[rgba(34,229,122,.1)] rounded-xl p-6">
        <h3 className="text-sm font-mono font-bold text-[#f2fff8] mb-3">
          Next Steps
        </h3>
        <div className="grid grid-cols-1 sm:grid-cols-3 gap-3">
          <Link
            href="/docs/api/countries"
            className="flex items-center gap-2 px-4 py-3 bg-[#0a100d] border border-[rgba(34,229,122,.06)] rounded-lg hover:border-[rgba(34,229,122,.2)] transition-all duration-300 group"
          >
            <Globe size={16} className="text-[#22e57a]" />
            <span className="text-sm font-mono text-[#c6d2ca] group-hover:text-[#22e57a] transition-colors">
              Countries API
            </span>
            <ChevronRight
              size={14}
              className="ml-auto text-[#4f6459] group-hover:text-[#22e57a] transition-colors"
            />
          </Link>
          <Link
            href="/docs/api/asn"
            className="flex items-center gap-2 px-4 py-3 bg-[#0a100d] border border-[rgba(34,229,122,.06)] rounded-lg hover:border-[rgba(34,229,122,.2)] transition-all duration-300 group"
          >
            <Network size={16} className="text-[#5c8aff]" />
            <span className="text-sm font-mono text-[#c6d2ca] group-hover:text-[#22e57a] transition-colors">
              ASN API
            </span>
            <ChevronRight
              size={14}
              className="ml-auto text-[#4f6459] group-hover:text-[#22e57a] transition-colors"
            />
          </Link>
          <Link
            href="/docs/formats/json"
            className="flex items-center gap-2 px-4 py-3 bg-[#0a100d] border border-[rgba(34,229,122,.06)] rounded-lg hover:border-[rgba(34,229,122,.2)] transition-all duration-300 group"
          >
            <Code size={16} className="text-[#f59e0b]" />
            <span className="text-sm font-mono text-[#c6d2ca] group-hover:text-[#22e57a] transition-colors">
              Data Formats
            </span>
            <ChevronRight
              size={14}
              className="ml-auto text-[#4f6459] group-hover:text-[#22e57a] transition-colors"
            />
          </Link>
        </div>
      </div>
    </div>
  );
}
